package com.cpf.starter.sftp;import org.apache.sshd.client.keyverifier.ServerKeyVerifier;import org.springframework.beans.factory.ObjectProvider;import org.springframework.boot.actuate.health.Health;import org.springframework.boot.actuate.health.HealthIndicator;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.jdbc.core.JdbcTemplate;
@AutoConfiguration @EnableConfigurationProperties(CpfSftpProperties.class) @ConditionalOnProperty(prefix="cpf.integration.sftp",name="enabled",havingValue="true") public class CpfSftpAutoConfiguration {@Bean JdbcCpfSftpTransferLedger cpfSftpTransferLedger(JdbcTemplate j){return new JdbcCpfSftpTransferLedger(j);}@Bean(destroyMethod="close") CpfSftpClient cpfSftpClient(CpfSftpProperties p,ServerKeyVerifier v,JdbcCpfSftpTransferLedger l){p.validate();return new CpfSftpClient(p,v,l);}@Bean("cpfSftpHealthIndicator") HealthIndicator health(CpfSftpProperties p){return ()->Health.up().withDetail("host",p.getHost()).withDetail("port",p.getPort()).build();}}
